 output={'experiment_verdict':'PASS — REVERSED-ORDER REPLICATION COMPLETED','performance_decision':decision,'N50k_followup':'NOT JUSTIFIED','historical_B05A':hist,'new_B05B':fresh,'order_sign_change':changed_sign,'order_sensitivity':'OBSERVED' if changed_sign else 'NOT CLEARLY OBSERVED','within_engine_between_run_ranges':ranges,'lookup_local_benefit':local,'stage_timings':stages,'confidence':'두 source별 관측2개, 두 pair뿐이다. 신뢰구간·통계적 유의성·순서의 인과효과를 주장하지 않는다.','not_summed_overlapping_stages':True,'N10k_cold':0,'N50k_cold':0,'N100k_cold':0,'N100k_feasibility':'NO-GO','next_action':'동결 최적화를 추가 고비용 측정 없이 실험 후보로만 보존한다.'}
 save(E/'comparison-summary.json',output)
 runs=[]
 for d in new:
  out=E/'raw'/d['id'];check=json.loads((out/'independent-verification.json').read_text());cfg=next(c for c in plan['runs'] if c['id']==d['id']);row={k:d[k] for k in ['id','ordinal','N','variant','on','engine_sha','backend_observation_sha256','client_source_digest','fixture_digest','template_sha256','H','D','start_utc','end_utc','accepted_before','accepted_after','completed_objects','staged_objects','committed_generation_objects','db_before','db_after','collector_closed','observation_expired','semantic_digest','E1','E2','E3','E4']};row.update(candidate_payload='8bd698368620394eece061f0b7b30b21172e814d2be92d153de40441a6f2a1f8' if d['variant']=='A' else '29bef95314c24d3f573328aaf60f5e7cc2987824e7ff39f35bfea4a2b38e3542',optimization_parent_payload='d0d9b35cefed5da51b08d77c3b7018d0a21318c0cdeb11a8418f2c1dde6232ae',Flutter_admission_artifact_sha256='8a2734c48f9355ba8930f75cf779d0da7c8fcdd19f297a8c3f78004e653da092',end_to_end_us=d['end_to_end_with_bounded_E4_us'],end_to_end_s=d['end_to_end_with_bounded_E4_us']/1e6,raw=str((out/'run.json').relative_to(R)),raw_sha256=sha((out/'run.json').read_bytes()),independent_verification=str((out/'independent-verification.json').relative_to(R)),independent_verification_sha256=sha((out/'independent-verification.json').read_bytes()),observation_leases=check['observation_leases'],renewals=check['renewals'],valid_completed=True,status='COMPLETED',diagnostics_pending=0);runs.append(row)
